"""Check local candidate contents. This does not approve or publish a release."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import re
import struct
import subprocess
import tempfile
import xml.etree.ElementTree as ET
import zipfile


def normalized(data):
    return data.replace(b'\r\n', b'\n').rstrip(b'\n')


def require(condition, message):
    if not condition:
        raise ValueError(message)


def check(root, version, sdk):
    target = root / 'target'
    ns = {'m': 'http://maven.apache.org/POM/4.0.0'}
    pom = target.parent / '.flattened-pom.xml'
    xml = ET.parse(pom).getroot()
    for field, expected in [('groupId', 'org.apache.casbin'), ('artifactId', 'jcasbin'), ('version', version)]:
        require(xml.findtext('m:' + field, namespaces=ns) == expected, 'Wrong flattened POM ' + field)
    require('incubating' in xml.findtext('m:description', namespaces=ns).lower(), 'POM incubation description missing')
    report = {'version': version, 'artifacts': {}, 'scope': 'local content check, not human review, signature verification or release approval'}
    for suffix in ('', '-sources', '-javadoc'):
        path = target / ('jcasbin-' + version + suffix + '.jar')
        with zipfile.ZipFile(path) as jar:
            files = {n: jar.read(n) for n in jar.namelist() if not n.endswith('/')}
        for legal in ('LICENSE', 'NOTICE', 'DISCLAIMER'):
            name = 'META-INF/' + legal
            expected = root / ('src/main/javadoc/LICENSE' if suffix == '-javadoc' and legal == 'LICENSE' else legal)
            require(files.get(name) == expected.read_bytes(), 'Wrong or missing ' + name + ' in ' + path.name)
        entry = {'sha512': hashlib.sha512(path.read_bytes()).hexdigest(), 'files': len(files)}
        if suffix == '':
            classes = [b for n, b in files.items() if n.endswith('.class')]
            require(classes and all(b[:4] == b'\xca\xfe\xba\xbe' and struct.unpack('>H', b[6:8])[0] == 52 for b in classes), 'Main classes are not Java8')
            require(files.get('META-INF/maven/org.apache.casbin/jcasbin/pom.xml') == pom.read_bytes(), 'Main JAR embedded POM differs')
            require(not any(n.startswith(('script-files/', 'resource-files/', 'legal/')) for n in files), 'Doc assets leaked into main JAR')
            entry['classes_major52'] = len(classes)
        if suffix == '-sources':
            java = {p.relative_to(root / 'src/main/java').as_posix(): p.read_bytes() for p in (root / 'src/main/java').rglob('*.java')}
            require({n: b for n, b in files.items() if n.endswith('.java')} == java, 'Sources JAR differs from source tree')
            entry['java_sources_matched'] = len(java)
        if suffix == '-javadoc':
            entry.update(check_docs(root, files, sdk))
        report['artifacts'][path.name] = entry
    report['artifacts'][pom.name] = {'sha512': hashlib.sha512(pom.read_bytes()).hexdigest()}
    return report


def check_docs(root, files, sdk):
    required = ['UPL-1.0.txt', 'jquery.md', 'jqueryUI.md', 'dejavufonts.md']
    for name in required:
        require(files.get('legal/' + name) == (root / 'src/main/javadoc/legal' / name).read_bytes(), 'Missing/wrong doc license: ' + name)
        require(('legal/' + name).encode() in files['META-INF/LICENSE'], 'License pointer missing: ' + name)
    for name in required[1:]:
        require(normalized(files['legal/' + name]) == normalized((sdk / 'legal/jdk.javadoc' / name).read_bytes()), 'SDK license does not match: ' + name)
    require('script.js' not in files and 'stylesheet.css' not in files, 'Legacy JDK8 resource layout')
    require(b'Generated by javadoc (25)' in files['org/casbin/jcasbin/main/Enforcer.html'], 'Wrong doclet generation')
    html = [n for n in files if n.endswith('.html')]
    for name in html:
        require(b'Apache Casbin (Incubating) is an effort undergoing incubation' in files[name]
                or b'javadoc/IndexRedirectWriter' in files[name], 'Missing incubation footer: ' + name)
    static = [n for n in files if Path(n).suffix.lower() in ('.js', '.css', '.svg', '.woff', '.woff2', '.png', '.gif', '.ttf')]
    with tempfile.TemporaryDirectory(prefix='jcasbin-doc-resources-') as tmp:
        executable = sdk / ('bin/jimage.exe' if os.name == 'nt' else 'bin/jimage')
        subprocess.run([str(executable), 'extract', '--include', 'glob:**/doclets/formats/html/resources/**', '--dir', tmp, str(sdk / 'lib/modules')], check=True, capture_output=True)
        resources = Path(tmp) / 'jdk.javadoc/jdk/javadoc/internal/doclets/formats/html/resources'
        for name in static:
            data = files[name]
            basename = Path(name).name
            if basename.endswith('-search-index.js'):
                require(not re.search(rb'GNU General Public License|jQuery JavaScript Library', data), 'Unexpected code in search index: ' + name)
                continue
            candidates = list(resources.rglob(basename))
            if candidates:
                matches = any(p.read_bytes() == data for p in candidates)
                if Path(name).suffix in ('.js', '.css', '.svg'):
                    matches = matches or any(normalized(p.read_bytes()) == normalized(data) for p in candidates)
                require(matches, 'Resource differs from verified doclet: ' + name)
            elif basename in ('script.js', 'search.js'):
                template = (resources / (basename + '.template')).read_bytes()
                require(normalized(data).startswith(normalized(template.split(b'*/', 1)[0])), 'Template notice changed: ' + name)
            else:
                raise ValueError('Unknown bundled resource: ' + name)
            if Path(name).suffix in ('.js', '.css', '.svg'):
                oracle = b'Licensed under the Universal Permissive License v 1.0' in data[:800]
                jquery = basename.startswith('jquery-')
                require(oracle or jquery, 'Unmapped resource license: ' + name)
                require(b'GNU General Public License' not in data[:1500], 'Unexpected GPL resource: ' + name)
    return {'html_pages': len(html), 'static_resources_checked': len(static), 'doc_license_texts': required}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('version')
    parser.add_argument('--javadoc-home', type=Path, required=True)
    args = parser.parse_args()
    try:
        result = check(Path(__file__).resolve().parents[2], args.version, args.javadoc_home.resolve())
    except (ValueError, KeyError, OSError, subprocess.CalledProcessError) as error:
        parser.exit(1, str(error) + '\n')
    print(json.dumps(result, indent=2))


if __name__ == '__main__':
    main()
